function tenetT7Service(service){
 const n=Number(service), km=n*10000;
 const work=['Заменить моторное масло и масляный фильтр','Заменить воздушный фильтр двигателя','Заменить фильтр кондиционера','Проверить уровни и состояние рабочих жидкостей','Проверить тормозные колодки, диски, шланги и стояночный тормоз','Проверить подвеску, рулевое управление, приводы, шины и крепёж','Проверить состояние DCT и отсутствие течей'];
 if(n%2===0)work.push('Заменить тормозную жидкость DOT4 и охлаждающую жидкость OAT по сроку 2 года / 40 000 км');
 if(n%3===0)work.push('Заменить свечи зажигания и внешний топливный фильтр');
 if(n===5)work.push('Для Fu Zhen AWD заменить масла раздаточной коробки и заднего редуктора (50 000 км)');
 if(n===6)work.push('Заменить жидкость DCT 730DHB/DHC (60 000 км; 4,25 ± 0,2 л Sinopec DCTF-GS)');
 return ['ТО-'+n+' · '+km.toLocaleString('ru-RU')+' км / '+(n*12)+' мес',work];
}
function tenetT8Service(service){
 const n=Number(service),km=n*10000;
 const work=['Заменить моторное масло и масляный фильтр (объём и допуск — по установленному двигателю SQRF4J16F или SQRF4J20)','Заменить воздушный фильтр двигателя и фильтр кондиционера','Проверить уровни рабочих жидкостей и отсутствие течей','Проверить тормоза, подвеску, рулевое управление, приводы, шины и момент затяжки колёс','Проверить уровень и состояние жидкости коробки передач'];
 if(n%2===0)work.push('Заменить охлаждающую жидкость OAT и тормозную жидкость DOT4: каждые 2 года или 40 000 км, что наступит раньше');
 if(n%3===0)work.push('Заменить свечи зажигания и внешний топливный фильтр: каждые 30 000 км');
 if(n===5)work.push('Если установлен Fu Zhen AWD: заменить масло раздаточной коробки TITAN EG 3201 (0,335–0,38 л) и заднего дифференциала Castrol SAF CARBON MOD (0,55 ± 0,05 л)');
 if(n===6){work.push('Для DCT 730DHB заменить DCTF-GS (5 л); для DCT 738DHA заменить DCTF-GS и наружный фильтр (6 л): каждые 60 000 км');work.push('Если установлен BorgWarner AWD: заменить жидкость устройства передачи крутящего момента Castrol HALBOT311 (0,63 ± 0,03 л)');}
 if(n===4||n===8)work.push('Для BorgWarner AWD при тяжёлой эксплуатации сверить замену масел раздатки и заднего дифференциала (интервал 38 000 км)');
 return ['ТО-'+n+' · '+km.toLocaleString('ru-RU')+' км / '+(n*12)+' мес',work];
}
vehicleSpecs['tenet:t9']={title:'TENET T9 — данные из официального руководства',source:'официальное руководство эксплуатации TENET T9, раздел «Техническое обслуживание»',items:['Двигатель SQRF4J20: моторное масло C5 0W-20 — 4,5 ± 0,2 л с одновременной заменой масляного фильтра','Автоматическая коробка 2WD: ATF-GS — 6,0 ± 0,2 л','Автоматическая коробка AWD: ATF-GS — 6,6 ± 0,2 л','Раздаточная коробка ZF AWD: Castrol SAF PD — 0,4 ± 0,02 л; задний редуктор SAF CARBON MOD — 0,6 ± 0,02 л','Раздаточная коробка Fu Zhen AWD: FUCHS TITAN EG 3202 — 0,335–0,38 л; задний редуктор SAF CARBON MOD — 0,55 ± 0,05 л','Раздаточная коробка GKN AWD: Castrol 75W-90 — 0,43 ± 0,03 л; задний редуктор Castrol BOT799 — 1 ± 0,03 л','Раздаточная коробка BorgWarner AWD: SAE 80W-90 — 0,31 ± 0,03 л; задний редуктор — 0,44 ± 0,03 л; устройство передачи момента Castrol HALBOT311 — 0,63 ± 0,03 л','Охлаждающая жидкость OAT: 7,5 ± 0,5 л','Тормозная жидкость: DOT4, уровень между MIN и MAX','Свечи зажигания: 3707AAG','Обычный межсервисный интервал: 10 000 км или 12 месяцев; для тяжёлых условий чаще проверять фильтры и тормоза']};
vehicleSpecs['jetour:x70']={title:'JETOUR X70 — данные из официального руководства',source:'официальное руководство эксплуатации JETOUR X70, разделы «Техническое обслуживание» и «Спецификация»',items:['Двигатель SQRE4T15C, 1,5 л Turbo, 1498 см³, 115 кВт; максимальный момент 210 Н·м','Коробка 626DHA (DCT6) или 6MF22A по комплектации; передний привод','Топливо: неэтилированный бензин с октановым числом 95; бак 55 л','Руководство требует выполнять плановое ТО по графику и использовать рекомендованные жидкости; таблица периодичности зависит от комплектации и условий эксплуатации','При тяжёлых условиях моторное масло и масляный фильтр заменяются чаще; фильтры двигателя и кондиционера также требуют сокращённого интервала','Точные заправочные объёмы масла и жидкости коробки нужно сверять с сервисной картой конкретной комплектации, так как руководство X70 содержит несколько вариантов']};
modelServiceNotes['jetour:x70']={1:['Заменить моторное масло и масляный фильтр по сервисной карте X70','Проверить DCT 626DHA/МКПП, тормоза, охлаждение и отсутствие течей'],2:['Заменить салонный фильтр','Проверить воздушный фильтр, ремни, патрубки, радиатор и кондиционер'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить подвеску, приводы, рулевое управление и шины'],4:['Проверить уровень жидкости 626DHA/МКПП по комплектации','Проверить тормозную систему, аккумулятор и электронные системы'],5:['Проверить систему охлаждения, ремни и ролики','Проверить коробку, приводы, подвеску и отсутствие течей'],6:['Заменить моторное масло, масляный и салонный фильтры по графику','Проверить тормозную жидкость, свечи, трансмиссию и крепёж'],7:['Проверить воздушный фильтр и систему вентиляции','Проверить тормоза, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и коробки','Проверить все уровни жидкостей, фильтры и электронные системы']};
vehicleSpecs['jetour:x70plus']={title:'JETOUR X70+ — данные из официального руководства',source:'руководство JETOUR X70+, таблица «Специальное масло и жидкость», и карта ТО JETOUR; https://jetour-ru.com/media/download/docs/1CG6gh__7pg6z2-rukovodstvo-po-ekspluatacii-x70-plus.pdf',items:['Актуальная российская комплектация: 1,6T, 190 л.с., 7G-DCT, передний привод; код двигателя и коробки сверить перед заменой','SQRF4J16: моторное масло C3 5W-30, 4,3 ± 0,2 л по таблице руководства','Для двигателя E4T15C в иных комплектациях: SN 5W-40, 4,7 ± 0,2 л','Если установлена 738DHA: Kunlun DCTF 7S, 6,5 ± 0,2 л; при сервисной замене ориентироваться на процедуру и фактический слив','Для 6DCT260: Sinopec DCTF-GS, 3,6 ± 0,1 л; для 6MF22A: Fuchs GL-4 75W-90, 2,2 ± 0,1 л','Охлаждающая жидкость: красная органическая −40 °C; тормозная жидкость DOT4','По карте JETOUR: масло двигателя и салонный фильтр на каждом ТО; воздушный фильтр через 20 000 км, свечи через 30 000 км, тормозная жидкость через 20 000 км, охлаждающая через 40 000 км','Топливо не ниже АИ-95, бак 55 л; заправочные ёмкости справочные и зависят от процедуры']};
modelServiceNotes['jetour:x70plus']={1:['Заменить моторное масло и масляный фильтр по сервисной карте X70+','Проверить DCT7, тормоза, охлаждение и отсутствие течей'],2:['Заменить салонный фильтр','Проверить воздушный фильтр, ремни, патрубки, радиатор и кондиционер'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить подвеску, рулевое управление, приводы и шины'],4:['Проверить уровень жидкости DCT7 по процедуре производителя','Проверить тормоза, аккумулятор и электронные системы'],5:['Проверить систему охлаждения, ремни и ролики','Проверить трансмиссию, подвеску и отсутствие течей'],6:['Заменить масло, масляный и салонный фильтры по графику','Проверить тормозную жидкость, свечи, DCT7 и крепёж'],7:['Проверить воздушный фильтр и систему вентиляции','Проверить тормоза, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и DCT7','Проверить все уровни жидкостей, фильтры и электронные системы']};
vehicleSpecs['jetour:t2']={title:'JETOUR T2 — данные из официальных материалов',source:'официальная модельная страница JETOUR T2 и руководство по эксплуатации JETOUR T2',items:['Турбированный двигатель 2,0 л, 245 л.с., 375 Н·м','В российской линейке встречаются 7-ступенчатая роботизированная 7DCT и 8-ступенчатая автоматическая 8AT','Полный привод с отдельными агрегатами трансмиссии по комплектации','ТО выполняется по графику руководства конкретной силовой установки; используются рекомендованные жидкости и оригинальные фильтры','Для точного объёма моторного масла, DCT/ATF, раздаточной коробки и редукторов нужно выбирать модификацию 7DCT или 8AT в сервисной карте']};
modelServiceNotes['jetour:t2']={1:['Заменить моторное масло и масляный фильтр по карте двигателя','Проверить 7DCT/8AT, раздаточную коробку, редукторы AWD и отсутствие течей'],2:['Заменить салонный фильтр','Проверить воздушный фильтр, тормоза, охлаждение и радиаторы'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить карданные валы, приводы, подвеску и шины'],4:['Проверить уровень жидкости 7DCT или 8AT по модификации','Проверить масла раздатки и редукторов AWD, крепёж и электронные системы'],5:['Проверить систему охлаждения, ремни, патрубки и аккумулятор','Проверить трансмиссию AWD, подвеску и отсутствие течей'],6:['Заменить масло, фильтры и тормозную жидкость по сроку','Проверить 7DCT/8AT, раздаточную коробку, редукторы и тормоза'],7:['Проверить воздушный фильтр и систему вентиляции','Проверить приводы, кардан, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и трансмиссии','Проверить все уровни жидкостей, фильтры, AWD-агрегаты и электронные системы']};
vehicleSpecs['jetour:dashing']={title:'JETOUR DASHING — данные из официального руководства',source:'официальное руководство JETOUR DASHING, стр. 234, и модельная страница JETOUR Россия; https://jetour-ru.com/media/download/docs/KnUGnk__rukovodstvo-po-ekspluatacii-dashing.pdf',items:['Российские комплектации: 1,5T/6DCT/2WD или 1,6T/8AT/AWD; перед работой сверить код двигателя и коробки','SQRE4T15C 1,5T: моторное масло с фильтром 4,7 ± 0,2 л; по руководству SM 5W-30, SM 5W-40 либо летнее SM 10W-40','SQRF4J16 1,6T: моторное масло с фильтром 4,3 ± 0,2 л; по руководству SM 5W-30','Если установлена 6DCT260: Sinopec DCTF-GS, ёмкость 3,6 ± 0,1 л; перед заменой сверить код коробки','Для 8AT текущей российской комплектации руководство не даёт подтверждённый объём ATF: сверить код агрегата и сервисную документацию','Охлаждающая жидкость — красная органическая −40 °C; в руководстве для 6DCT260 указано 9,5 л, для других комплектаций сверить систему','Тормозная жидкость DOT4; топливо АИ-95, бак 57 л','Заправочные ёмкости являются данными руководства; фактический объём при сервисной замене зависит от процедуры']};
modelServiceNotes['jetour:dashing']={1:['Заменить моторное масло и масляный фильтр по карте двигателя','Проверить 6DCT/8AT, тормоза, охлаждение и отсутствие течей'],2:['Заменить салонный фильтр CN95','Проверить воздушный фильтр, радиаторы, ремни и кондиционер'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить подвеску, рулевое управление, приводы и шины'],4:['Проверить уровень жидкости 6DCT или 8AT по модификации','Для AWD проверить масла раздатки и заднего редуктора'],5:['Проверить охлаждение, патрубки, ремни и аккумулятор','Проверить трансмиссию, приводы, подвеску и отсутствие течей'],6:['Заменить масло и фильтры по графику; тормозную жидкость по сроку','Проверить 6DCT/8AT, тормоза, полный привод и крепёж'],7:['Проверить воздушный фильтр и систему вентиляции','Проверить тормоза, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и трансмиссии','Проверить все уровни жидкостей, фильтры, AWD-агрегаты и электронные системы']};
