vehicleSpecs['jetour:x90plus']={title:'JETOUR X90+ — официальные технические данные',source:'официальная модельная страница и спецификация JETOUR X90+',items:['Двигатель 1,6 л Turbo: 190 л.с., 275 Н·м; коробка 7DCT, передний привод','Двигатель 2,0 л Turbo: 245 л.с., 375 Н·м; коробка 7DCT, передний привод','Для версии 2.0T доступна 8-ступенчатая АКПП с полным приводом; встречаются 5- и 7-местные исполнения','Топливо: бензин АИ-95; бак 57 л','Точные заправочные объёмы масла двигателя, 7DCT/8AT, раздатки и редукторов выбирать по конкретной модификации и сервисной карте']};
