function tenetT4Service(service){
 const n=Number(service),km=n*10000;
 const work=['Заменить моторное масло 4,7 ± 0,2 л и масляный фильтр (SQRE4G15C/SQRE4T15C; допуск масла — по двигателю)','Заменить воздушный фильтр двигателя и фильтр кондиционера','Проверить уровни жидкостей и отсутствие течей','Проверить тормоза, подвеску, рулевое управление, приводы, шины и колёсный крепёж','Проверить состояние и уровень жидкости установленной коробки передач'];
 if(n%2===0)work.push('Заменить тормозную жидкость DOT4 и охлаждающую жидкость OAT: каждые 2 года или 40 000 км, что наступит раньше');
 if(n%3===0)work.push('Заменить свечи зажигания и внешний топливный фильтр: каждые 30 000 км');
 work.push('Если установлена МКПП 517MHA: заменить FUCHS GL-4 75W-90 (2,1 ± 0,1 л; ежегодно или 30 000 км)');
 if(n===3||n===6)work.push('Если установлен ремень ГРМ: заменить по сроку 3 года или 100 000 км; для цепи плановая замена не требуется');
 if(n===4)work.push('Если установлена CVT 018CHA/025CHC: первая замена Shell CVTF WCF-1 и внешнего фильтра при 40 000 км; заправочная ёмкость 7,3 ± 0,2 л, при замене сверить объём слитого');
 if(n===6)work.push('Если установлена DCT 730DHE: заменить DCTF-GS (5,6 ± 0,3 л); для коробки 626DHB из графика сверить индекс агрегата перед заменой');
 if(n===3||n===6)work.push('Если установлен угольный фильтр адсорбера: заменить по сроку 3 года или 60 000 км');
 return ['ТО-'+n+' · '+km.toLocaleString('ru-RU')+' км / '+(n*12)+' мес',work];
}
function jetourOfficialService(model,service){
 const n=Number(service),km=n*10000;
 const work=[
  'Заменить моторное масло и масляный фильтр по установленному двигателю',
  'Заменить салонный фильтр',
  'Проверить ремень привода вспомогательных агрегатов',
  'Проверить уровень и герметичность системы охлаждения, тормозной системы и коробки передач',
  'Проверить тормозные механизмы, колодки и диски, подвеску и рулевое управление',
  'Проверить шины, давление и затяжку колёсного крепежа',
  'Проверить АКБ, освещение, топливную систему, отопление и кондиционер',
  'Смазать дверные петли и защёлки, считать коды неисправностей и сбросить межсервисный интервал'
 ];
 if(n%2===0){work.push('Заменить воздушный фильтр двигателя');work.push('Заменить тормозную жидкость DOT4 (каждые 20 000 км или 24 мес)');}
 else work.push('Проверить воздушный фильтр двигателя');
 if(n%3===0)work.push('Заменить свечи зажигания (каждые 30 000 км или 36 мес)');
 else work.push('Проверить свечи зажигания');
 if(n%4===0)work.push('Заменить охлаждающую жидкость (каждые 40 000 км или 48 мес)');
 if(n%3===0)work.push('Если установлена МКПП: заменить трансмиссионное масло (каждые 30 000 км или 36 мес)');
 if(n%4===0)work.push('Если установлена коробка DF727A: заменить трансмиссионную жидкость (каждые 40 000 км или 48 мес)');
 if(n%5===0)work.push('Если установлена коробка 830AHA или 840AHA: заменить ATF (каждые 50 000 км или 60 мес)');
 if(n%6===0)work.push('Если установлена 6DCT260, 730DHA, 740DHB или 738DHA: заменить трансмиссионную жидкость (каждые 60 000 км или 72 мес)');
 if(['t1','t2'].includes(model)){
  work.push('Проверить раздаточную коробку, задний дифференциал и муфту полного привода');
  if(n%4===0)work.push('Заменить масло раздаточной коробки (T1/T2: каждые 40 000 км или 48 мес)');
  if(n%6===0)work.push('Заменить масла заднего дифференциала и муфты 4WD при наличии (T1/T2: каждые 60 000 км или 72 мес)');
 }
 if(['dashing','x90plus'].includes(model)){
  work.push('Для AWD проверить раздаточную коробку, задний дифференциал и муфту полного привода');
  if(n%5===0)work.push('Для AWD заменить масло раздаточной коробки (каждые 50 000 км или 60 мес)');
  if(model==='dashing'&&n%5===0)work.push('Для DASHING AWD заменить масло заднего дифференциала/муфты при наличии (каждые 50 000 км или 60 мес)');
  if(model==='x90plus'&&n%6===0)work.push('Для X90+ AWD заменить масло заднего дифференциала/муфты при наличии (каждые 60 000 км или 72 мес)');
 }
 if(model==='x70plus')work.push('Перед заменой жидкости 7DCT сверить код коробки: для 738DHA регламент карты — 60 000 км');
 if(model==='x70'||model==='x50')work.push('Сверить код коробки по автомобилю перед применением условного интервала МКПП или DCT');
 return ['ТО-'+n+' · '+km.toLocaleString('ru-RU')+' км / '+(n*12)+' мес',work];
}
