const finalBox=document.createElement('section');finalBox.className='card';finalBox.innerHTML='<h3>Проверка механика</h3><p class="hint">Подтвердите операции, которые легко забыть</p><div id="final-checks"></div>';$('detail').insertBefore(finalBox,$('finish'));function finalChecksForJob(){const common=['Масло залито в нужном объёме','Масляный фильтр закручен и уплотнение проверено','Сливная пробка закручена с установленной шайбой','Проверено отсутствие течей после запуска','Уровни жидкостей проверены','Колёса и снятый крепёж затянуты','Разъёмы, датчики и защиты установлены','Инструмент убран из моторного отсека'];const operations=(current.items||[]).map(item=>item.text);const hasOperation=pattern=>operations.some(item=>pattern.test(item));const cabin=hasOperation(/заменить.*салонн.*фильтр/i),air=hasOperation(/заменить.*воздушн.*фильтр/i);if(cabin||air)common.splice(4,0,cabin&&air?'Салонный и воздушный фильтры установлены правильно':cabin?'Салонный фильтр установлен правильно':'Воздушный фильтр установлен правильно');if(hasOperation(/заменить.*тормозн.*жидкост/i)){common.splice(5,0,'Тормозная жидкость залита до уровня MIN/MAX');common.splice(6,0,'Тормозная система прокачана, педаль проверена')}if(hasOperation(/заменить.*свеч/i))common.splice(6,0,'Свечи зажигания затянуты и катушки подключены');const key=(current.brand||'')+':'+(current.model||'').toLowerCase();if(/DCT|T55|T77|T90|Tiggo 4|Tiggo 7|Tiggo 8|Arrizo 8/i.test(current.model||'')){common.push('Проверена правильная жидкость роботизированной коробки и её объём');common.push('Фильтр и сливная пробка коробки установлены и затянуты');common.push('Разъёмы коробки и датчики подключены, течей нет')}if(/AWD|Tiggo 7L|Tiggo 8|Tiggo 9|T8/i.test(current.model||'')){common.push('Проверены уровни масел раздаточной коробки и дифференциалов AWD')}if(/Hybrid|PHEV/i.test(current.model||'')){common.push('Высоковольтная система отключена/подключена по процедуре, ошибок нет');common.push('Проверены контуры охлаждения гибридной системы')}return common}function renderFinal(){if(!current)return;const defaults=finalChecksForJob();if(!Array.isArray(current.finalItems)||current.finalVersion!==2){current.finalItems=defaults.map(text=>({text,done:false}));current.finalVersion=2;save()}$('final-checks').innerHTML=current.finalItems.map((x,i)=>`<label class="check ${x.done?'done':''}"><input type="checkbox" data-final="${i}" ${x.done?'checked':''}><span>${x.text}</span></label>`).join('');document.querySelectorAll('[data-final]').forEach(e=>e.onchange=()=>{current.finalItems[+e.dataset.final].done=e.checked;save();renderFinal();syncFinish()});syncFinish()}function syncFinish(){if(!current)return;$('finish').disabled=current.items.some(x=>!x.done)||!current.finalItems||current.finalItems.some(x=>!x.done)}new MutationObserver(()=>{renderFinal()}).observe($('checklist'),{childList:true});
const timerBox=document.createElement('section');timerBox.className='card';timerBox.innerHTML='<h3>Время работы</h3><p id="timer-value" class="hint">00:00:00</p><button id="timer-toggle" class="secondary wide">Начать работу</button><button id="timer-reset" class="danger wide">Сбросить время</button>';$('detail').insertBefore(timerBox,finalBox);let timerHandle=null;function timerSeconds(){if(!current)return 0;let t=current.timer||{total:0,running:false,started:0};return t.total+(t.running?Math.max(0,Math.floor((Date.now()-t.started)/1000)):0)}function renderTimer(){if(!current)return;let n=timerSeconds(),h=String(Math.floor(n/3600)).padStart(2,'0'),m=String(Math.floor(n%3600/60)).padStart(2,'0'),s=String(n%60).padStart(2,'0');$('timer-value').textContent=h+':'+m+':'+s;$('timer-toggle').textContent=current.timer&&current.timer.running?'Пауза':'Начать работу'}function timerTick(){renderTimer();if(current&&current.timer&&current.timer.running)save()}$('timer-toggle').onclick=()=>{if(!current)return;current.timer=current.timer||{total:0,running:false,started:0};if(current.timer.running){current.timer.total=timerSeconds();current.timer.running=false;current.timer.started=0}else{current.timer.running=true;current.timer.started=Date.now()}save();renderTimer()};$('timer-reset').onclick=()=>{if(current){current.timer={total:0,running:false,started:0};save();renderTimer()}};setInterval(timerTick,1000);
